import openpyxl

wb = openpyxl.load_workbook('/root/protein_expression.xlsx', data_only=True)
task = wb['Task']

# Check yellow cells and blue cells formatting
print("=== Task sheet cell fills (rows 9-27, cols A-L) ===")
for row in [9, 10]:
    for col in range(1, 13):
        cell = task.cell(row=row, column=col)
        fill = cell.fill
        if fill and fill.fgColor and fill.fgColor.rgb and fill.fgColor.rgb != '00000000':
            print(f"  {openpyxl.utils.get_column_letter(col)}{row}: fill={fill.fgColor.rgb}, value={cell.value}")

# Check row 23 headers
print("\n=== Row 23 (stat headers) ===")
for col in range(1, 13):
    v = task.cell(row=23, column=col).value
    if v is not None:
        print(f"  {openpyxl.utils.get_column_letter(col)}23 = {v}")

# Check rows 24-27 for labels and any existing content
print("\n=== Rows 24-27 ===")
for row in range(24, 28):
    for col in range(1, 13):
        v = task.cell(row=row, column=col).value
        if v is not None:
            print(f"  {openpyxl.utils.get_column_letter(col)}{row} = {v}")

# Check rows 31-41
print("\n=== Rows 30-41 ===")
for row in range(30, 42):
    for col in range(1, 13):
        v = task.cell(row=row, column=col).value
        if v is not None:
            print(f"  {openpyxl.utils.get_column_letter(col)}{row} = {v}")

# Check what column the stats headers are in row 23
print("\n=== Row 23-27 columns B-L ===")
for row in range(23, 28):
    for col in range(2, 13):
        cell = task.cell(row=row, column=col)
        v = cell.value
        fill = cell.fill
        fill_info = ""
        if fill and fill.fgColor and fill.fgColor.rgb and fill.fgColor.rgb != '00000000':
            fill_info = f" [fill={fill.fgColor.rgb}]"
        if v is not None or fill_info:
            print(f"  {openpyxl.utils.get_column_letter(col)}{row} = {v}{fill_info}")

